// ---------------------------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------------------------

const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const uniqSorted = (list) => [...new Set(list)].sort(cmp);
const md = (o) => (o && isObj(o.metadata) ? o.metadata : {});
const refKey = (r) => `${r.namespace}/${r.name}`;
const byRef = (a, b) => cmp(a.namespace, b.namespace) || cmp(a.name, b.name);
const ownKeys = (o) => (isObj(o) ? Object.keys(o).sort(cmp) : []);
const listItems = (v) => (Array.isArray(v) ? v : isObj(v) && Array.isArray(v.items) ? v.items : []);
const PFLAG_TRUE = new Set(['1', 't', 'T', 'TRUE', 'true', 'True']);
const flagTrue = (v) => PFLAG_TRUE.has(String(v));
const BOOL_TRUE = new Set(['1', 't', 'true']);
const annotationTrue = (v) => BOOL_TRUE.has(String(v).trim().toLowerCase());
const isSnippetKey = (key) => /snippet$/i.test(key); // not allow-snippet-annotations
const lineCount = (v) => (String(v).trim() === '' ? 0 : String(v).trim().split(/\r?\n/).length);

export class UsageError extends Error {
  constructor(key, params = {}) { super(key); this.key = key; this.params = params; }
}
export class FatalError extends Error {
  constructor(key, params = {}) { super(key); this.key = key; this.params = params; }
}

// ---------------------------------------------------------------------------------------------
// Argument parsing
// ---------------------------------------------------------------------------------------------

const VALUE_OPTIONS = { '--context': 'context', '--kubeconfig': 'kubeconfig', '--kubectl': 'kubectl', '--from-dir': 'fromDir', '--out': 'out', '--lang': 'lang' };
const SWITCH_OPTIONS = { '--anonymize': 'anonymize', '--quiet': 'quiet', '-h': 'help', '--help': 'help', '-v': 'version', '--version': 'version' };

// Returns the options object; throws UsageError for unknown options, missing or repeated values.
export function parseArgs(argv) {
  const o = { context: null, kubeconfig: null, kubectl: null, fromDir: null, out: null, lang: null, anonymize: false, quiet: false, help: false, version: false };
  const seen = new Set();
  for (let i = 0; i < argv.length; i++) {
    const arg = String(argv[i]);
    const eq = arg.startsWith('--') ? arg.indexOf('=') : -1;
    const name = eq > 0 ? arg.slice(0, eq) : arg;
    if (SWITCH_OPTIONS[name]) {
      if (eq > 0) throw new UsageError('usage.noValueExpected', { option: name });
      o[SWITCH_OPTIONS[name]] = true;
      continue;
    }
    if (!VALUE_OPTIONS[name]) throw new UsageError(arg.startsWith('-') ? 'usage.unknownOption' : 'usage.unexpectedArgument', { option: arg });
    if (seen.has(name)) throw new UsageError('usage.repeated', { option: name });
    seen.add(name);
    let value;
    if (eq > 0) value = arg.slice(eq + 1);
    else { value = argv[i + 1]; i++; }
    if (value === undefined || value === '' || (eq < 0 && String(value).startsWith('-'))) throw new UsageError('usage.missingValue', { option: name });
    o[VALUE_OPTIONS[name]] = String(value);
  }
  if (o.lang !== null && o.lang !== 'en' && o.lang !== 'fr') throw new UsageError('usage.badLang', { value: o.lang });
  if (o.fromDir !== null && (o.kubeconfig !== null || o.kubectl !== null)) throw new UsageError('usage.fromDirConflict', { option: o.kubeconfig !== null ? '--kubeconfig' : '--kubectl' });
  return o;
}

// --lang wins; otherwise French when LC_ALL (or, if unset, LANG) starts with "fr".
export function resolveLang(lang, env = {}) {
  if (lang === 'en' || lang === 'fr') return lang;
  const locale = env.LC_ALL || env.LANG || '';
  return /^fr/i.test(locale) ? 'fr' : 'en';
}

// ---------------------------------------------------------------------------------------------
// kubectl: the only external program, behind one allowlist
// ---------------------------------------------------------------------------------------------

const GET_RESOURCES = new Set([
  'ingressclasses.networking.k8s.io', 'ingresses.networking.k8s.io', 'deployments.apps', 'daemonsets.apps', 'services',
  'configmap', 'nginxingresscontrollers.approuting.kubernetes.azure.com', 'gatewayclasses.gateway.networking.k8s.io',
  'gateways.gateway.networking.k8s.io', 'httproutes.gateway.networking.k8s.io', 'crd',
]);
const NAMED_GET = { configmap: 'json', crd: 'jsonpath={.metadata.annotations}' }; // resource -> the only output format
const DNS_LABEL = /^[a-z0-9]([-a-z0-9]{0,61}[a-z0-9])?$/;
const DNS_SUBDOMAIN = /^[a-z0-9]([-a-z0-9.]{0,251}[a-z0-9])?$/;

// True only for: `version -o json`, `config current-context`, and `get <allowlisted resource>`
// with -A, -n <namespace>, one name (configmap, crd) and -o json (crd: -o jsonpath=...), followed
// by the global options --request-timeout=60s, --context=<x> and --kubeconfig=<x>. Any token that
// mentions a secret, in any form, is refused.
export function isAllowedKubectlCall(args) {
  if (!Array.isArray(args) || args.length === 0 || !args.every((a) => typeof a === 'string')) return false;
  const core = [];
  for (const a of args) {
    if (a === REQUEST_TIMEOUT || /^--context=./s.test(a) || /^--kubeconfig=./s.test(a)) continue;
    core.push(a);
  }
  if (core.some((a) => /secret/i.test(a) || /(^|[,/.])sec($|[,/.])/i.test(a))) return false;
  if (core.length === 3 && core[0] === 'version' && core[1] === '-o' && core[2] === 'json') return true;
  if (core.length === 2 && core[0] === 'config' && core[1] === 'current-context') return true;
  if (core[0] !== 'get' || !GET_RESOURCES.has(core[1])) return false;
  const resource = core[1];
  const named = Object.prototype.hasOwnProperty.call(NAMED_GET, resource);
  let output = null; let namespace = null; let name = null; let all = false;
  for (let i = 2; i < core.length; i++) {
    const a = core[i];
    if (a === '-A') { if (all || named) return false; all = true; } else if (a === '-o') {
      if (output !== null || i + 1 >= core.length) return false;
      output = core[++i];
    } else if (a === '-n') {
      if (namespace !== null || i + 1 >= core.length || resource !== 'configmap') return false;
      namespace = core[++i];
      if (!DNS_LABEL.test(namespace)) return false;
    } else {
      if (!named || name !== null || !DNS_SUBDOMAIN.test(a)) return false;
      name = a;
    }
  }
  if (named) return name !== null && output === NAMED_GET[resource] && (resource !== 'configmap' || namespace !== null);
  return output === 'json';
}

export function kubectlArgs(core, opts = {}) {
  const args = [...core, REQUEST_TIMEOUT];
  if (opts.context) args.push(`--context=${opts.context}`);
  if (opts.kubeconfig) args.push(`--kubeconfig=${opts.kubeconfig}`);
  return args;
}

// The real runner: kubectl started directly (no shell), output captured, nothing inherited.
export function spawnRunner(kubectl = 'kubectl') {
  return (args) => {
    const r = spawnSync(kubectl, args, { encoding: 'utf8', maxBuffer: 1024 ** 3, windowsHide: true });
    return { status: r.status, stdout: r.stdout || '', stderr: r.stderr || '', error: r.error ? (r.error.code || r.error.message) : null };
  };
}

// Every kubectl call goes through here. A call outside the allowlist is a bug: it throws.
export function runKubectl(runner, core, opts = {}) {
  const args = kubectlArgs(core, opts);
  if (!isAllowedKubectlCall(args)) throw new Error(`internal error: kubectl call refused by the allowlist: ${args.join(' ')}`);
  const r = runner(args) || {};
  const result = { status: r.status === undefined ? null : r.status, stdout: String(r.stdout || ''), stderr: String(r.stderr || ''), error: r.error || null };
  result.ok = result.status === 0 && !result.error;
  return result;
}

// ---------------------------------------------------------------------------------------------
// Collection: a snapshot of the cluster objects, live (kubectl) or offline (--from-dir)
// ---------------------------------------------------------------------------------------------

function emptySnapshot(mode, context) {
  return {
    mode, context, version: null, ingressClasses: null, ingresses: [], deployments: null, daemonsets: null, services: null,
    configMaps: null, nics: null, gatewayClasses: null, gateways: null, httpRoutes: null, gatewayCrd: null, warnings: [], notes: [],
  };
}

const firstLine = (s) => String(s || '').trim().split(/\r?\n/)[0].slice(0, 300);
const parseJson = (s) => { try { return JSON.parse(s); } catch { return undefined; } };
const typeAbsent = (stderr) => /doesn't have a resource type|the server could not find the requested resource|NotFound|not found/i.test(stderr);

// Keeps only items of the expected kind (an export never feeds a Secret into the analysis).
function itemsOfKind(doc, kind) {
  return listItems(doc).filter((o) => isObj(o) && (o.kind === undefined || o.kind === kind));
}

// CRD annotations as printed by `kubectl get crd ... -o jsonpath={.metadata.annotations}`.
export function parseCrdAnnotations(text) {
  const raw = String(text || '').trim();
  if (!raw) return null;
  let obj = parseJson(raw);
  if (!isObj(obj)) {
    obj = {};
    for (const k of ['gateway.networking.k8s.io/bundle-version', 'gateway.networking.k8s.io/channel']) {
      const m = raw.match(new RegExp(`${k.replace(/[.]/g, '\\.')}["']?\\s*[:=]\\s*["']?([^"',}\\s]+)`));
      if (m) obj[k] = m[1];
    }
  }
  const bundleVersion = typeof obj['gateway.networking.k8s.io/bundle-version'] === 'string' ? obj['gateway.networking.k8s.io/bundle-version'] : null;
  const channel = typeof obj['gateway.networking.k8s.io/channel'] === 'string' ? obj['gateway.networking.k8s.io/channel'] : null;
  return bundleVersion || channel ? { bundleVersion, channel } : null;
}

// ConfigMaps named by the flags of the detected ingress-nginx controllers, deduplicated and sorted.
export function controllerConfigMapRefs(snapshot, catalog = CATALOG) {
  const refs = new Map();
  for (const c of detectControllers(snapshot, catalog)) {
    for (const flag of ['--configmap', '--tcp-services-configmap', '--udp-services-configmap']) {
      const value = c.flags[flag];
      if (!value) continue;
      const ref = parseNamespacedName(value);
      const key = ref ? refKey(ref) : value;
      if (!refs.has(key)) refs.set(key, { value, ref });
    }
  }
  return [...refs.keys()].sort(cmp).map((k) => refs.get(k));
}

function parseNamespacedName(value) {
  const v = String(value || '').trim();
  const m = v.match(/^([^/\s]+)\/([^/\s]+)$/);
  if (!m || v.includes('$(')) return null;
  return { namespace: m[1], name: m[2] };
}

// Live mode. `runner(args) => { status, stdout, stderr, error }` is injectable for tests.
export function collectLive(opts = {}, { runner, catalog = CATALOG } = {}) {
  const run = runner || spawnRunner(opts.kubectl || 'kubectl');
  const snap = emptySnapshot('live', opts.context || null);
  const warn = (code, r, params = {}) => snap.warnings.push({ code, params, detail: r ? firstLine(r.stderr || r.error) : '' });
  const call = (core) => {
    const r = runKubectl(run, core, opts);
    if (r.error === 'ENOENT') throw new FatalError('fatal.kubectlMissing', { kubectl: opts.kubectl || 'kubectl' });
    return r;
  };
  const getList = (core, kind) => {
    const r = call(core);
    const doc = r.ok ? parseJson(r.stdout) : undefined;
    return { r, items: doc === undefined ? null : itemsOfKind(doc, kind) };
  };

  // 1. kubectl version (also tells whether kubectl starts at all)
  let r = call(['version', '-o', 'json']);
  const version = parseJson(r.stdout);
  if (isObj(version)) snap.version = version;
  if (!r.ok || !isObj(version) || !isObj(version.serverVersion)) warn('warn.version', r);

  // 2. current context
  if (!opts.context) {
    r = call(['config', 'current-context']);
    const ctx = r.stdout.trim();
    if (r.ok && ctx) snap.context = ctx;
    else { snap.context = 'unknown-context'; warn('warn.context', r); }
  }

  // 3. IngressClasses
  let g = getList(['get', 'ingressclasses.networking.k8s.io', '-o', 'json'], 'IngressClass');
  if (g.items) snap.ingressClasses = g.items; else warn('warn.ingressClasses', g.r);

  // 4. Ingresses: fatal on failure
  g = getList(['get', 'ingresses.networking.k8s.io', '-A', '-o', 'json'], 'Ingress');
  if (!g.items) throw new FatalError('fatal.ingresses', { detail: firstLine(g.r.stderr || g.r.error) });
  snap.ingresses = g.items;

  // 5, 6. Workloads and Services
  for (const [field, resource, kind, code] of [
    ['deployments', 'deployments.apps', 'Deployment', 'warn.deployments'],
    ['daemonsets', 'daemonsets.apps', 'DaemonSet', 'warn.daemonsets'],
    ['services', 'services', 'Service', 'warn.services'],
  ]) {
    g = getList(['get', resource, '-A', '-o', 'json'], kind);
    if (g.items) snap[field] = g.items; else warn(code, g.r);
  }

  // 7. The controllers' own ConfigMaps, by name
  snap.configMaps = [];
  for (const { value, ref } of controllerConfigMapRefs(snap, catalog)) {
    if (!ref) { snap.warnings.push({ code: 'warn.configmapUnresolved', params: { value }, detail: '' }); continue; }
    const core = ['get', 'configmap', ref.name, '-n', ref.namespace, '-o', 'json'];
    if (!isAllowedKubectlCall(kubectlArgs(core, opts))) { snap.warnings.push({ code: 'warn.configmapSkipped', params: { ref }, detail: '' }); continue; }
    r = call(core);
    const cm = r.ok ? parseJson(r.stdout) : undefined;
    if (isObj(cm) && cm.kind === 'ConfigMap') snap.configMaps.push(cm);
    else warn('warn.configmap', r, { ref });
  }

  // 8. Optional resource types: silent when the type does not exist
  for (const [field, core, kind] of [
    ['nics', ['get', 'nginxingresscontrollers.approuting.kubernetes.azure.com', '-o', 'json'], 'NginxIngressController'],
    ['gatewayClasses', ['get', 'gatewayclasses.gateway.networking.k8s.io', '-o', 'json'], 'GatewayClass'],
    ['gateways', ['get', 'gateways.gateway.networking.k8s.io', '-A', '-o', 'json'], 'Gateway'],
    ['httpRoutes', ['get', 'httproutes.gateway.networking.k8s.io', '-A', '-o', 'json'], 'HTTPRoute'],
  ]) {
    g = getList(core, kind);
    if (g.items) snap[field] = g.items;
    else if (!typeAbsent(g.r.stderr)) snap.notes.push({ code: 'note.optionalUnreadable', params: { resource: core[1] }, detail: firstLine(g.r.stderr || g.r.error) });
  }
  r = call(['get', 'crd', 'gateways.gateway.networking.k8s.io', '-o', 'jsonpath={.metadata.annotations}']);
  if (r.ok) snap.gatewayCrd = parseCrdAnnotations(r.stdout);
  return snap;
}

// Offline mode: the files written by the export commands of the README.
export const OFFLINE_FILES = [
  ['ingresses', 'ingresses.json', 'Ingress'],
  ['ingressClasses', 'ingressclasses.json', 'IngressClass'],
  ['deployments', 'deployments.json', 'Deployment'],
  ['daemonsets', 'daemonsets.json', 'DaemonSet'],
  ['services', 'services.json', 'Service'],
  ['configMaps', 'configmaps.json', 'ConfigMap'],
  ['version', 'version.json', null],
  ['nics', 'nginxingresscontrollers.json', 'NginxIngressController'],
  ['gatewayClasses', 'gatewayclasses.json', 'GatewayClass'],
  ['gateways', 'gateways.json', 'Gateway'],
  ['httpRoutes', 'httproutes.json', 'HTTPRoute'],
];

export function loadFromDir(dir, opts = {}) {
  let stat = null;
  try { stat = fs.statSync(dir); } catch { stat = null; }
  if (!stat || !stat.isDirectory()) throw new FatalError('fatal.fromDir', { dir });
  const snap = emptySnapshot('offline', opts.context || 'unknown-context');
  for (const [field, file, kind] of OFFLINE_FILES) {
    const full = path.join(dir, file);
    let text;
    try { text = fs.readFileSync(full, 'utf8'); } catch (x) {
      if (field === 'ingresses') throw new FatalError('fatal.fromDirIngresses', { file: full });
      if (x && x.code === 'ENOENT') snap.notes.push({ code: 'note.fileMissing', params: { file }, detail: '' });
      else snap.warnings.push({ code: 'warn.fileUnreadable', params: { file }, detail: String((x && x.code) || '') });
      continue;
    }
    const doc = parseJson(text.replace(/^﻿/, ''));
    const ok = kind === null ? isObj(doc) : isObj(doc) || Array.isArray(doc);
    if (!ok) {
      if (field === 'ingresses') throw new FatalError('fatal.fromDirIngresses', { file: full });
      snap.warnings.push({ code: 'warn.fileInvalid', params: { file }, detail: '' });
      continue;
    }
    if (kind === null) { snap[field] = doc; continue; }
    const all = listItems(isObj(doc) && doc.kind === kind ? { items: [doc] } : doc);
    const kept = itemsOfKind(isObj(doc) && doc.kind === kind ? { items: [doc] } : doc, kind);
    if (kept.length < all.length) snap.warnings.push({ code: 'warn.fileOtherKinds', params: { file, count: all.length - kept.length }, detail: '' });
    snap[field] = kept;
  }
  return snap;
}

// ---------------------------------------------------------------------------------------------
// Analysis: controllers, attribution, routes, annotations, ConfigMaps, defaults, network
// ---------------------------------------------------------------------------------------------

export function assertCatalog(catalog) {
  if (!catalog || !isObj(catalog.meta)) throw new FatalError('fatal.catalogEmpty');
}

const indexCache = new WeakMap();
function buildIndex(entries) {
  const exact = new Map();
  const prefixes = [];
  for (const e of entries || []) {
    if (!e || typeof e.key !== 'string') continue;
    if (e.match === 'prefix') prefixes.push(e); else if (!exact.has(e.key)) exact.set(e.key, e);
  }
  prefixes.sort((a, b) => b.key.length - a.key.length || cmp(a.key, b.key));
  return {
    lookup(key) {
      const hit = exact.get(key);
      if (hit) return hit;
      for (const p of prefixes) if (key.startsWith(p.key)) return p;
      return null;
    },
  };
}
function catalogIndexes(catalog) {
  let idx = indexCache.get(catalog);
  if (!idx) {
    const eco = (scope) => buildIndex((catalog.ecosystem || []).filter((e) => e.scope === scope && !e.key.startsWith('Service.spec.')));
    idx = {
      annotations: buildIndex(catalog.annotations),
      configmap: buildIndex(catalog.configmap),
      flags: buildIndex(catalog.flags),
      ecoIngress: eco('ingress'),
      ecoClass: eco('ingressclass'),
      ecoService: eco('service'),
      serviceFields: (catalog.ecosystem || []).filter((e) => e.scope === 'service' && e.key.startsWith('Service.spec.')).sort((a, b) => cmp(a.key, b.key)),
      defaults: new Map((catalog.defaults || []).map((d) => [d.id, d])),
    };
    indexCache.set(catalog, idx);
  }
  return idx;
}

export function lookupCatalog(catalog, kind, key) {
  const idx = catalogIndexes(catalog);
  const which = { annotation: idx.annotations, configmap: idx.configmap, flag: idx.flags }[kind];
  if (which) return which.lookup(key);
  if (kind === 'ecosystem') return (catalog.ecosystem || []).find((e) => e.key === key) || null;
  return null;
}

// valueRules: the first matching rule wins. equals, in and contains compare trimmed, case-insensitive
// values; regex is a JavaScript RegExp on the raw value; exists always matches.
const regexCache = new Map();
function compiledRegex(source) {
  if (!regexCache.has(source)) {
    let re = null;
    try { re = new RegExp(source); } catch { re = null; }
    regexCache.set(source, re);
  }
  return regexCache.get(source);
}
export function matchValueRule(rules, value) {
  const raw = value === undefined || value === null ? '' : String(value);
  const v = raw.trim().toLowerCase();
  const norm = (x) => String(x).trim().toLowerCase();
  for (let i = 0; i < (Array.isArray(rules) ? rules.length : 0); i++) {
    const test = (rules[i] && rules[i].test) || {};
    let hit = false;
    if (test.op === 'exists') hit = true;
    else if (test.op === 'equals') hit = v === norm(test.value);
    else if (test.op === 'in') hit = Array.isArray(test.value) && test.value.some((x) => v === norm(x));
    else if (test.op === 'contains') hit = v.includes(norm(test.value));
    else if (test.op === 'regex') { const re = compiledRegex(String(test.value)); hit = re !== null && re.test(raw); }
    if (hit) return i;
  }
  return -1;
}

// Catalog facts copied into the model for one key (and the value rule that matched, if any).
function catalogInfo(entry, ruleIndex) {
  const rule = ruleIndex >= 0 ? entry.valueRules[ruleIndex] : null;
  const targets = {};
  for (const t of TARGETS) targets[t] = (rule && rule.targets && rule.targets[t]) || (entry.targets && entry.targets[t] && entry.targets[t].support) || 'unknown';
  return {
    catalogKey: entry.key,
    bucket: rule ? rule.bucket : entry.bucket,
    rule: rule ? { index: ruleIndex, when: rule.when } : null,
    gatewayApi: entry.gatewayApi ? { construct: entry.gatewayApi.construct, channel: entry.gatewayApi.channel, support: entry.gatewayApi.support } : null,
    targets,
    note: rule ? { en: rule.note_en, fr: rule.note_fr } : { en: entry.note_en, fr: entry.note_fr },
    noteCode: null,
    ingress2gateway: entry.ingress2gateway || null,
    confidence: entry.confidence || null,
  };
}
function syntheticInfo(bucket, support, noteCode) {
  const targets = {};
  for (const t of TARGETS) targets[t] = support;
  return { catalogKey: null, bucket, rule: null, gatewayApi: null, targets, note: null, noteCode, ingress2gateway: null, confidence: null };
}

function matchPattern(match, pattern, value) {
  if (typeof pattern !== 'string' || typeof value !== 'string') return false;
  if (match === 'prefix') return value.startsWith(pattern);
  if (match === 'suffix') return value.endsWith(pattern);
  return value === pattern;
}
// Most specific match: exact, then prefix, then suffix; longer patterns first.
function bestMatch(list, field, value) {
  const rank = { exact: 0, prefix: 1, suffix: 2 };
  const hits = (list || []).filter((x) => matchPattern(x.match || 'exact', x[field], value));
  hits.sort((a, b) => (rank[a.match || 'exact'] - rank[b.match || 'exact']) || (b[field].length - a[field].length) || cmp(a[field], b[field]));
  return hits[0] || null;
}

export function parseImage(image) {
  const s = String(image || '');
  const at = s.indexOf('@');
  const digest = at >= 0 ? s.slice(at + 1) : null;
  const ref = at >= 0 ? s.slice(0, at) : s;
  const slash = ref.lastIndexOf('/');
  const colon = ref.lastIndexOf(':');
  const hasTag = colon > slash;
  return { repository: hasTag ? ref.slice(0, colon) : ref, tag: hasTag ? ref.slice(colon + 1) : null, digest };
}

// "v1.13.10-13" -> { major: 1, minor: 13, patch: 10, suffix: '-13' }; null when not a version.
export function parseVersion(text) {
  const m = String(text || '').match(/^v?(\d+)\.(\d+)\.(\d+)([-+].*)?$/);
  if (!m) return null;
  return { major: Number(m[1]), minor: Number(m[2]), patch: Number(m[3]), suffix: m[4] || '', text: `${m[1]}.${m[2]}.${m[3]}${m[4] || ''}` };
}
// A pre-release suffix ("-beta.0") sorts before the release; build metadata ("+x") is ignored.
function compareVersions(a, b) {
  const d = a.major - b.major || a.minor - b.minor || a.patch - b.patch;
  if (d !== 0) return d;
  const pa = a.suffix.startsWith('-') ? 1 : 0;
  const pb = b.suffix.startsWith('-') ? 1 : 0;
  return pb - pa;
}

// SPEC 5.1: fixed when a listed version has the same major.minor and the version is greater or
// equal, or when its major.minor is above every listed one.
export function isVersionFixed(version, fixedList) {
  const fixed = (fixedList || []).map(parseVersion).filter(Boolean);
  if (!fixed.length) return false;
  const same = fixed.filter((f) => f.major === version.major && f.minor === version.minor);
  if (same.length) return same.some((f) => compareVersions(version, f) >= 0);
  return fixed.every((f) => version.major > f.major || (version.major === f.major && version.minor > f.minor));
}

// Verdict for one controller: unrecognised image, no version, vendor build, vulnerable or patched.
export function cveVerdict(controller, meta) {
  if (!controller.imageFamily) return { status: 'unrecognisedImage', unfixed: [] };
  const v = controller.version ? parseVersion(controller.version) : null;
  if (!v) return { status: 'noVersion', unfixed: [] };
  if (!controller.imageFamily.semverComparable) return { status: 'vendor', reason: 'family', unfixed: [] };
  const finals = (String((meta.versions && meta.versions.ingressNginx) || '').match(/\d+\.\d+\.\d+/g) || []).map(parseVersion);
  if (finals.length) {
    const sameLine = finals.filter((f) => f.major === v.major && f.minor === v.minor);
    const above = sameLine.length ? sameLine.every((f) => compareVersions(v, f) > 0) : finals.every((f) => compareVersions(v, f) > 0);
    if (above) return { status: 'vendor', reason: 'aboveUpstream', unfixed: [] };
  }
  const unfixed = (meta.vulnerabilities || []).filter((x) => !isVersionFixed(v, x.fixed)).map((x) => x.id);
  return { status: unfixed.length ? 'vulnerable' : 'patched', unfixed };
}

// pflag: --flag=value and --flag value; a bool flag alone means true; the last occurrence wins.
// Only FLAG_DEFAULTS flags are kept. $(VAR) is expanded from `vars` only; $$ is a literal $.
export function parseControllerFlags(tokens, vars = {}) {
  const set = {};
  for (let i = 0; i < tokens.length; i++) {
    const tok = String(tokens[i]);
    if (tok === '--') break;
    if (!tok.startsWith('--')) continue;
    const eq = tok.indexOf('=');
    const name = eq > 0 ? tok.slice(0, eq) : tok;
    if (!Object.prototype.hasOwnProperty.call(FLAG_DEFAULTS, name)) continue;
    let value;
    if (eq > 0) value = tok.slice(eq + 1);
    else if (BOOL_FLAGS.has(name)) value = 'true';
    else if (i + 1 < tokens.length) value = String(tokens[++i]);
    else continue;
    set[name] = value.replace(/\$\$|\$\(([A-Za-z_][A-Za-z0-9_]*)\)/g, (m, v) => (m === '$$' ? '$' : Object.prototype.hasOwnProperty.call(vars, v) ? vars[v] : m));
  }
  const flags = {};
  for (const k of Object.keys(FLAG_DEFAULTS)) flags[k] = Object.prototype.hasOwnProperty.call(set, k) ? set[k] : FLAG_DEFAULTS[k];
  return { flags, flagsSet: Object.keys(set).sort(cmp) };
}

// Variables usable in flag values: env entries set from the pod's own namespace (fieldRef
// metadata.namespace). Other env entries are never read, so their values cannot leak.
function namespaceVars(container, namespace) {
  const vars = {};
  for (const e of Array.isArray(container.env) ? container.env : []) {
    if (!e || typeof e.name !== 'string') continue;
    const fieldPath = e.valueFrom && e.valueFrom.fieldRef && e.valueFrom.fieldRef.fieldPath;
    if (fieldPath === 'metadata.namespace') vars[e.name] = namespace;
    else delete vars[e.name];
  }
  return vars;
}

// SPEC 5.1: ingress-nginx runs in a container whose image matches detection.nginxImages, or whose
// command or first argument is /nginx-ingress-controller.
export function detectControllers(snapshot, catalog = CATALOG) {
  assertCatalog(catalog);
  const det = catalog.meta.detection || {};
  const appNs = det.appRouting && det.appRouting.namespace;
  const found = [];
  for (const [kind, list] of [['Deployment', snapshot.deployments], ['DaemonSet', snapshot.daemonsets]]) {
    for (const w of list || []) {
      const m = md(w);
      const podSpec = (w.spec && w.spec.template && w.spec.template.spec) || {};
      const podLabels = (w.spec && w.spec.template && isObj(md(w.spec.template).labels)) ? md(w.spec.template).labels : {};
      for (const c of Array.isArray(podSpec.containers) ? podSpec.containers : []) {
        if (!isObj(c)) continue;
        const img = parseImage(c.image);
        const family = bestMatch(det.nginxImages, 'repository', img.repository);
        const command = Array.isArray(c.command) ? c.command.map(String) : [];
        const args = Array.isArray(c.args) ? c.args.map(String) : [];
        const byBinary = command.includes(CONTROLLER_BINARY) || args[0] === CONTROLLER_BINARY;
        if (!family && !byBinary) continue;
        const argv = [...command, ...args];
        const at = argv.indexOf(CONTROLLER_BINARY);
        const tokens = at >= 0 ? argv.slice(at + 1) : args;
        const namespace = String(m.namespace || '');
        const { flags, flagsSet } = parseControllerFlags(tokens, namespaceVars(c, namespace));
        const version = parseVersion(img.tag);
        found.push({
          kind, namespace, name: String(m.name || ''), container: String(c.name || ''),
          replicas: kind === 'Deployment' ? (Number.isInteger(w.spec && w.spec.replicas) ? w.spec.replicas : 1)
            : (w.status && Number.isInteger(w.status.desiredNumberScheduled) ? w.status.desiredNumberScheduled : null),
          image: String(c.image || ''), repository: img.repository, tag: img.tag, digest: img.digest,
          imageFamily: family ? { repository: family.repository, family: family.family, label: family.label, semverComparable: family.semverComparable === true, source: family.source } : null,
          version: version ? version.text : null,
          flags, flagsSet,
          podLabels: Object.fromEntries(ownKeys(podLabels).map((k) => [k, String(podLabels[k])])),
          appRouting: (appNs && namespace === appNs) || podLabels['app.kubernetes.io/managed-by'] === 'aks-app-routing-operator',
        });
      }
    }
  }
  found.sort((a, b) => cmp(a.kind, b.kind) || cmp(a.namespace, b.namespace) || cmp(a.name, b.name) || cmp(a.container, b.container));
  found.forEach((c, i) => { c.id = `c${i + 1}`; });
  return found;
}

function readIngressClass(o, det) {
  const m = md(o);
  const name = String(m.name || '');
  const controller = o.spec && typeof o.spec.controller === 'string' ? o.spec.controller : '';
  const anns = isObj(m.annotations) ? m.annotations : {};
  return { name, controller, isDefault: String(anns[DEFAULT_CLASS_ANNOTATION] || '').trim() === 'true', annotations: anns, label: labelClass(name, controller, det) };
}
// Who a class belongs to: by spec.controller (detection.ingressClassControllers), else by name for
// classes whose controller string is undocumented (detection.ingressClassNames).
function labelClass(name, controller, det) {
  const byController = controller ? bestMatch(det.ingressClassControllers, 'value', controller) : null;
  if (byController) return { family: byController.family, label: byController.label, source: byController.source, via: 'controller' };
  const byName = (det.ingressClassNames || []).find((x) => x.name === name);
  if (byName) return { family: byName.family, label: byName.label, source: byName.source, via: 'name' };
  return null;
}
const nginxFamily = (family) => family === 'ingress-nginx' || family === 'aks-app-routing-nginx';

function ownsClass(c, cl) {
  return cl.controller === c.flags['--controller-class'] || (flagTrue(c.flags['--ingress-class-by-name']) && cl.name === c.flags['--ingress-class']);
}

function readIngress(o) {
  const m = md(o);
  const spec = isObj(o.spec) ? o.spec : {};
  const annotations = isObj(m.annotations) ? m.annotations : {};
  const hasClassAnnotation = Object.prototype.hasOwnProperty.call(annotations, CLASS_ANNOTATION);
  const ing = {
    namespace: String(m.namespace || ''), name: String(m.name || ''), annotations, spec,
    className: typeof spec.ingressClassName === 'string' && spec.ingressClassName !== '' ? spec.ingressClassName : null,
    hasClassAnnotation, classAnnotation: hasClassAnnotation ? String(annotations[CLASS_ANNOTATION]) : null,
    routes: [], hosts: [], tlsHosts: [], tlsSecrets: [], backends: [], defaultBackend: false, implementationSpecific: 0,
  };
  const seen = new Set();
  for (const rule of Array.isArray(spec.rules) ? spec.rules : []) {
    if (!isObj(rule)) continue;
    const host = typeof rule.host === 'string' && rule.host !== '' ? rule.host : '*';
    if (host !== '*') ing.hosts.push(host);
    const paths = rule.http && Array.isArray(rule.http.paths) ? rule.http.paths : [];
    for (const p of paths) {
      if (!isObj(p)) continue;
      const pathValue = typeof p.path === 'string' && p.path !== '' ? p.path : '/';
      if (p.pathType === 'ImplementationSpecific') ing.implementationSpecific++;
      const svc = p.backend && p.backend.service && p.backend.service.name;
      if (typeof svc === 'string' && svc) ing.backends.push(svc);
      const key = `${host}\u0000${pathValue}`;
      if (!seen.has(key)) { seen.add(key); ing.routes.push({ host, path: pathValue, rawPath: typeof p.path === 'string' ? p.path : '', pathType: typeof p.pathType === 'string' ? p.pathType : null }); }
    }
  }
  for (const t of Array.isArray(spec.tls) ? spec.tls : []) {
    if (!isObj(t)) continue;
    for (const h of Array.isArray(t.hosts) ? t.hosts : []) if (typeof h === 'string' && h) ing.tlsHosts.push(h);
    if (typeof t.secretName === 'string' && t.secretName) ing.tlsSecrets.push(t.secretName);
  }
  if (isObj(spec.defaultBackend)) {
    ing.defaultBackend = true;
    const svc = spec.defaultBackend.service && spec.defaultBackend.service.name;
    if (typeof svc === 'string' && svc) ing.backends.push(svc);
  }
  ing.hosts = uniqSorted(ing.hosts);
  ing.tlsHosts = uniqSorted(ing.tlsHosts);
  ing.tlsSecrets = uniqSorted(ing.tlsSecrets);
  ing.backends = uniqSorted(ing.backends);
  ing.routeCount = ing.routes.length + (ing.defaultBackend ? 1 : 0);
  return ing;
}

function deepInspectBlocked(ing) {
  const values = [];
  for (const rule of Array.isArray(ing.spec.rules) ? ing.spec.rules : []) {
    if (!isObj(rule)) continue;
    if (typeof rule.host === 'string' && rule.host) values.push(rule.host);
    for (const p of (rule.http && Array.isArray(rule.http.paths)) ? rule.http.paths : []) if (isObj(p) && typeof p.path === 'string') values.push(p.path);
  }
  for (const t of Array.isArray(ing.spec.tls) ? ing.spec.tls : []) {
    if (!isObj(t)) continue;
    if (typeof t.secretName === 'string') values.push(t.secretName);
    for (const h of Array.isArray(t.hosts) ? t.hosts : []) if (typeof h === 'string') values.push(h);
  }
  return values.some((v) => DEEP_INSPECT_PATTERNS.some((re) => re.test(v)));
}

// SPEC 5.2: ingress-nginx's own decision (GetIngressClass), then its filters. First match wins.
export function decideIngress(c, ing, ownedClassNames) {
  let via;
  if (ing.className !== null) {
    via = 'field';
    if (!ownedClassNames.has(ing.className)) return { served: false, via, reason: 'classNotOwned' };
  } else if (ing.hasClassAnnotation) {
    via = 'annotation';
    if (ing.classAnnotation === '' || ing.classAnnotation !== c.flags['--ingress-class']) return { served: false, via, reason: 'annotationMismatch' };
  } else {
    via = 'classless';
    if (!flagTrue(c.flags['--watch-ingress-without-class'])) return { served: false, via, reason: 'classless' };
  }
  const watchNs = c.flags['--watch-namespace'];
  if (watchNs && watchNs !== ing.namespace) return { served: false, via, reason: 'namespace' };
  if (flagTrue(c.flags['--disable-catch-all']) && ing.defaultBackend) return { served: false, via, reason: 'catchAll' };
  if (flagTrue(c.flags['--deep-inspect']) && deepInspectBlocked(ing)) return { served: false, via, reason: 'deepInspect' };
  return { served: true, via, selectorNotEvaluated: c.flags['--watch-namespace-selector'] !== '' };
}

// Why no ingress-nginx controller serves an Ingress: another controller's class, or a reason.
function placeUnserved(ing, decisions, classByName, det) {
  const filtered = decisions.find((d) => ['namespace', 'catchAll', 'deepInspect'].includes(d.reason));
  if (filtered) return { status: 'unassigned', reason: filtered.reason, controller: filtered.id, className: ing.className };
  const byClassName = (name) => {
    const cl = classByName.get(name);
    const label = cl ? cl.label : labelClass(name, '', det);
    if (label && !nginxFamily(label.family)) return { status: 'other', label: label.label, family: label.family, className: name };
    if (label) return { status: 'unassigned', reason: 'nginxClassNoController', className: name };
    if (cl) return { status: 'unassigned', reason: 'classUnknownController', className: name, controllerString: cl.controller };
    return null;
  };
  if (ing.className !== null) return byClassName(ing.className) || { status: 'unassigned', reason: 'classMissing', className: ing.className };
  if (ing.hasClassAnnotation) return byClassName(ing.classAnnotation) || { status: 'unassigned', reason: 'annotationNoController', className: ing.classAnnotation };
  return { status: 'unassigned', reason: 'classless', className: null };
}

// Annotation key -> how it is read: under a controller prefix (catalog annotation or unknown),
// ecosystem key, F5 NGINX key, default prefix ignored by a custom-prefix controller, or not ours.
function classifyAnnotation(key, prefixes, idx) {
  for (const prefix of prefixes) {
    if (key.startsWith(`${prefix}/`)) {
      const name = key.slice(prefix.length + 1);
      const entry = idx.annotations.lookup(name);
      return entry ? { kind: 'annotation', prefix, name, entry } : { kind: 'unknown', prefix, name };
    }
  }
  const eco = idx.ecoIngress.lookup(key);
  if (eco) return { kind: 'ecosystem', prefix: null, name: key, entry: eco };
  if (F5_PREFIXES.some((p) => key.startsWith(p))) return { kind: 'f5', prefix: null, name: key };
  if (key.startsWith(`${DEFAULT_PREFIX}/`)) return { kind: 'otherPrefix', prefix: null, name: key };
  return null;
}

function infoFor(cls, value) {
  if (cls.entry) return catalogInfo(cls.entry, matchValueRule(cls.entry.valueRules, value));
  if (cls.kind === 'f5') return syntheticInfo('none', 'n/a', 'f5Key');
  if (cls.kind === 'otherPrefix') return syntheticInfo('unknown', 'unknown', 'otherPrefix');
  return syntheticInfo('unknown', 'unknown', 'unknownKey');
}

const bucketRank = (b) => { const i = BUCKET_ORDER.indexOf(b); return i < 0 ? BUCKET_ORDER.length : i; };

// Aggregates (key, matched rule) rows; values are kept up to MAX_VALUES distinct, snippets as line counts.
function rowCollector() {
  const rows = new Map();
  return {
    add(id, base, value, ref) {
      let row = rows.get(id);
      if (!row) { row = { ...base, refs: new Map(), values: new Set(), lines: new Set() }; rows.set(id, row); }
      if (ref) row.refs.set(refKey(ref), ref);
      if (row.snippet) row.lines.add(lineCount(value)); else row.values.add(String(value));
    },
    list() {
      return [...rows.values()].map((r) => {
        const values = r.snippet ? [...r.lines].sort((a, b) => a - b).map((n) => ({ lines: n })) : [...r.values].sort(cmp).map((v) => ({ value: v }));
        const refs = [...r.refs.values()].sort(byRef);
        const out = { ...r, ingressCount: refs.length, ingresses: refs, values: values.slice(0, MAX_VALUES), moreValues: Math.max(0, values.length - MAX_VALUES) };
        delete out.refs; delete out.lines;
        return out;
      });
    },
  };
}
const rowOrder = (a, b) => bucketRank(a.bucket) - bucketRank(b.bucket) || (b.ingressCount || 0) - (a.ingressCount || 0)
  || cmp(displayKey(a), displayKey(b)) || ((a.rule ? a.rule.index : -1) - (b.rule ? b.rule.index : -1));
export const displayKey = (row) => (row.prefix ? `${row.prefix}/${row.name}` : row.name);

function nowIso(now) {
  const d = now instanceof Date ? now : new Date(now);
  return Number.isNaN(d.getTime()) ? new Date(0).toISOString() : d.toISOString();
}

// The whole analysis. Pure: same snapshot, catalog and clock give the same model.
export function analyze(snapshot, { catalog = CATALOG, now = new Date(), anonymized = false } = {}) {
  assertCatalog(catalog);
  const meta = catalog.meta;
  const det = meta.detection || {};
  const idx = catalogIndexes(catalog);

  // Controllers and IngressClasses
  const controllers = detectControllers(snapshot, catalog);
  const classes = (snapshot.ingressClasses || []).map((o) => readIngressClass(o, det)).sort((a, b) => cmp(a.name, b.name));
  const classByName = new Map(classes.map((cl) => [cl.name, cl]));
  for (const c of controllers) {
    c.ownedClasses = classes.filter((cl) => ownsClass(c, cl)).map((cl) => cl.name);
    c.owned = new Set(c.ownedClasses);
    c.prefix = c.flags['--annotations-prefix'] || DEFAULT_PREFIX;
    c.verdict = cveVerdict(c, meta);
    c.served = [];
  }
  const byId = new Map(controllers.map((c) => [c.id, c]));

  // Ingresses: attribution
  const ings = (snapshot.ingresses || []).map(readIngress).sort(byRef);
  const ambiguities = [];
  for (const ing of ings) {
    const decisions = controllers.map((c) => ({ id: c.id, ...decideIngress(c, ing, c.owned) }));
    const served = decisions.filter((d) => d.served);
    ing.servedBy = served.map((d) => d.id);
    ing.via = served.length ? served[0].via : null;
    ing.selectorNotEvaluated = served.some((d) => d.selectorNotEvaluated);
    for (const d of served) byId.get(d.id).served.push(ing);
    ing.placement = served.length ? null : placeUnserved(ing, decisions, classByName, det);
    if (served.length > 1) ambiguities.push({ type: 'multipleControllers', ingress: { namespace: ing.namespace, name: ing.name }, controllers: ing.servedBy });
    if (ing.className !== null && ing.hasClassAnnotation && ing.classAnnotation !== ing.className) {
      ambiguities.push({ type: 'fieldAnnotationMismatch', ingress: { namespace: ing.namespace, name: ing.name }, className: ing.className, annotation: ing.classAnnotation });
    }
  }
  const servedIngs = ings.filter((i) => i.servedBy.length);

  // Annotations of the served Ingresses
  const annotationRows = rowCollector();
  const otherKeys = new Set();
  const bucketsByIngress = new Map();
  for (const ing of servedIngs) {
    const prefixes = uniqSorted(ing.servedBy.map((id) => byId.get(id).prefix));
    const ref = { namespace: ing.namespace, name: ing.name };
    const buckets = {};
    for (const key of ownKeys(ing.annotations)) {
      const value = ing.annotations[key];
      const cls = classifyAnnotation(key, prefixes, idx);
      if (!cls) { otherKeys.add(key); continue; }
      const info = infoFor(cls, value);
      const id = `${cls.kind}\u0000${cls.prefix || ''}\u0000${cls.name}\u0000${info.rule ? info.rule.index : -1}`;
      annotationRows.add(id, { kind: cls.kind, prefix: cls.prefix, name: cls.name, snippet: isSnippetKey(cls.name), ...info }, value, ref);
      (buckets[info.bucket] = buckets[info.bucket] || new Set()).add(key);
    }
    bucketsByIngress.set(ing, buckets);
  }
  const annotations = annotationRows.list().sort(rowOrder);

  // IngressClass annotations (ecosystem scope ingressclass) on classes owned by ingress-nginx
  const classRows = [];
  for (const cl of classes) {
    if (!controllers.some((c) => c.owned.has(cl.name)) && !(cl.label && nginxFamily(cl.label.family))) continue;
    for (const key of ownKeys(cl.annotations)) {
      const entry = idx.ecoClass.lookup(key);
      if (!entry) continue;
      const value = String(cl.annotations[key]);
      classRows.push({ className: cl.name, key, value, ...catalogInfo(entry, matchValueRule(entry.valueRules, value)) });
    }
  }

  // Regex path matching: use-regex, or a rewrite-target that differs from the path, on any
  // Ingress of a host turns every path of that host into a regex (F8 §6; template.go).
  const regexHosts = [];
  const regexHostKeys = new Set();
  for (const c of controllers) {
    const hosts = new Map();
    for (const ing of c.served) {
      const useRegex = annotationTrue(ing.annotations[`${c.prefix}/use-regex`] || '');
      const rewrite = ing.annotations[`${c.prefix}/rewrite-target`];
      for (const r of ing.routes) {
        let trigger = null;
        if (useRegex) trigger = 'use-regex';
        else if (typeof rewrite === 'string' && rewrite !== '' && rewrite !== r.path) trigger = 'rewrite-target';
        if (!trigger) continue;
        if (!hosts.has(r.host)) hosts.set(r.host, new Map());
        hosts.get(r.host).set(`${refKey(ing)}\u0000${trigger}`, { namespace: ing.namespace, name: ing.name, key: `${c.prefix}/${trigger}` });
      }
    }
    for (const host of [...hosts.keys()].sort(cmp)) {
      regexHostKeys.add(`${c.id}\u0000${host}`);
      const onHost = c.served.filter((i) => i.routes.some((r) => r.host === host)).map((i) => ({ namespace: i.namespace, name: i.name }));
      regexHosts.push({ controller: c.id, host, ingresses: onHost.sort(byRef), triggers: [...hosts.get(host).values()].sort((a, b) => byRef(a, b) || cmp(a.key, b.key)) });
    }
  }

  // Scope (SPEC 5.3): routes = distinct (host, path) pairs + one per spec.defaultBackend
  const routeKeys = new Set(); const regexRouteKeys = new Set();
  const hosts = new Set(); const tlsHosts = new Set(); const tlsSecrets = new Set(); const backends = new Set(); const namespaces = new Set();
  let defaultBackends = 0; let implementationSpecific = 0; let classless = 0;
  for (const ing of servedIngs) {
    namespaces.add(ing.namespace);
    for (const r of ing.routes) {
      const k = `${r.host}\u0000${r.path}`;
      routeKeys.add(k);
      if (ing.servedBy.some((id) => regexHostKeys.has(`${id}\u0000${r.host}`))) regexRouteKeys.add(k);
    }
    ing.hosts.forEach((h) => hosts.add(h));
    ing.tlsHosts.forEach((h) => tlsHosts.add(h));
    ing.tlsSecrets.forEach((s) => tlsSecrets.add(`${ing.namespace}/${s}`));
    ing.backends.forEach((s) => backends.add(`${ing.namespace}/${s}`));
    if (ing.defaultBackend) defaultBackends++;
    implementationSpecific += ing.implementationSpecific;
    if (ing.via === 'classless') classless++;
  }
  const scope = {
    ingressesTotal: ings.length, ingresses: servedIngs.length, namespaces: namespaces.size, routes: routeKeys.size + defaultBackends,
    hosts: hosts.size, tlsHosts: tlsHosts.size, tlsSecrets: tlsSecrets.size, implementationSpecificPaths: implementationSpecific,
    regexPaths: regexRouteKeys.size, backendServices: backends.size, defaultBackends, classless,
    otherControllers: ings.filter((i) => i.placement && i.placement.status === 'other').length,
    unassigned: ings.filter((i) => i.placement && i.placement.status === 'unassigned').length,
  };

  // Controller ConfigMaps (SPEC 5.5)
  const cmByRef = new Map();
  for (const cm of snapshot.configMaps || []) cmByRef.set(refKey({ namespace: String(md(cm).namespace || ''), name: String(md(cm).name || '') }), cm);
  const configMaps = [];
  const tcpUdp = [];
  const cmGroups = new Map();
  for (const c of controllers) {
    for (const flag of ['--configmap', '--tcp-services-configmap', '--udp-services-configmap']) {
      const value = c.flags[flag];
      if (!value) continue;
      const ref = parseNamespacedName(value);
      const key = `${flag}\u0000${ref ? refKey(ref) : value}`;
      if (!cmGroups.has(key)) cmGroups.set(key, { flag, value, ref, controllers: [] });
      cmGroups.get(key).controllers.push(c.id);
    }
  }
  for (const key of [...cmGroups.keys()].sort(cmp)) {
    const g = cmGroups.get(key);
    const cm = g.ref ? cmByRef.get(refKey(g.ref)) : undefined;
    const data = cm && isObj(cm.data) ? cm.data : {};
    const base = { controllers: g.controllers, namespace: g.ref ? g.ref.namespace : null, name: g.ref ? g.ref.name : null, unresolved: g.ref ? null : g.value, found: !!cm };
    if (g.flag === '--configmap') {
      const keys = ownKeys(data).map((k) => {
        const value = String(data[k]);
        const entry = idx.configmap.lookup(k);
        const snippet = isSnippetKey(k);
        const info = entry ? catalogInfo(entry, matchValueRule(entry.valueRules, value)) : syntheticInfo('unknown', 'unknown', 'unknownKey');
        return { key: k, snippet, ...(snippet ? { lines: lineCount(value) } : { value }), sameAsDefault: !!(entry && entry.nginxDefault !== null && entry.nginxDefault !== undefined && value.trim() === String(entry.nginxDefault).trim()), ...info };
      }).sort((a, b) => bucketRank(a.bucket) - bucketRank(b.bucket) || cmp(a.key, b.key));
      configMaps.push({ ...base, keys });
    } else {
      const flagEntry = idx.flags.lookup(g.flag);
      const entries = ownKeys(data).map((port) => {
        const target = String(data[port]);
        const parts = target.split(':');
        const svc = parseNamespacedName(parts[0]);
        return { port, namespace: svc ? svc.namespace : null, service: svc ? svc.name : null, servicePort: parts.length > 1 ? parts[1] : null, options: parts.slice(2).join(':') || null, raw: svc ? null : target };
      });
      tcpUdp.push({ ...base, protocol: g.flag === '--tcp-services-configmap' ? 'TCP' : 'UDP', flag: g.flag, entries, ...(flagEntry ? catalogInfo(flagEntry, -1) : syntheticInfo('unknown', 'unknown', 'unknownKey')) });
    }
  }

  // Security flags
  const security = [];
  for (const c of controllers) {
    if (c.verdict.status === 'vulnerable') security.push({ code: 'cveUnfixed', controller: c.id, cves: c.verdict.unfixed });
    if (c.verdict.status === 'vendor') security.push({ code: 'vendorBuild', controller: c.id, reason: c.verdict.reason });
    if (c.flags['--validating-webhook']) {
      const unfixed = ['vulnerable', 'patched'].includes(c.verdict.status) ? WEBHOOK_CVES.filter((id) => c.verdict.unfixed.includes(id)) : null;
      security.push({ code: 'webhook', controller: c.id, cves: WEBHOOK_CVES, unfixed });
    }
  }
  for (const cm of configMaps) {
    const allow = cm.keys.find((k) => k.key === 'allow-snippet-annotations');
    if (allow && String(allow.value).trim().toLowerCase() === 'true') security.push({ code: 'snippetsAllowed', configMap: { namespace: cm.namespace, name: cm.name } });
    const snippets = cm.keys.filter((k) => k.snippet && k.lines > 0).map((k) => k.key);
    if (snippets.length) security.push({ code: 'configSnippets', configMap: { namespace: cm.namespace, name: cm.name }, keys: snippets });
  }
  const snippetRows = annotations.filter((r) => r.snippet && (r.kind === 'annotation' || r.kind === 'unknown'));
  if (snippetRows.length) {
    const refs = new Map();
    for (const r of snippetRows) for (const ref of r.ingresses) refs.set(refKey(ref), ref);
    security.push({ code: 'snippetAnnotations', keys: uniqSorted(snippetRows.map((r) => r.name)), ingressCount: refs.size });
  }

  // Defaults that change (SPEC 5.6), as configured in this cluster
  const defaults = (catalog.defaults || []).slice().sort((a, b) => Number(String(a.id).slice(1)) - Number(String(b.id).slice(1))).map((d) => {
    const inCluster = [];
    for (const k of d.controlledBy || []) {
      if (k.kind === 'configmap') {
        for (const cm of configMaps) {
          const hit = cm.keys.find((x) => x.key === k.key);
          if (hit) inCluster.push({ kind: 'configmap', key: k.key, configMap: { namespace: cm.namespace, name: cm.name }, ...(hit.snippet ? { lines: hit.lines } : { value: hit.value }) });
        }
      } else if (k.kind === 'flag') {
        if (!Object.prototype.hasOwnProperty.call(FLAG_DEFAULTS, k.key)) { inCluster.push({ kind: 'flagNotRead', key: k.key }); continue; }
        for (const c of controllers) if (c.flagsSet.includes(k.key)) inCluster.push({ kind: 'flag', key: k.key, controller: c.id, value: c.flags[k.key] });
      } else if (k.kind === 'annotation') {
        const count = servedIngs.filter((ing) => ing.servedBy.some((id) => Object.prototype.hasOwnProperty.call(ing.annotations, `${byId.get(id).prefix}/${k.key}`))).length;
        if (count) inCluster.push({ kind: 'annotation', key: k.key, ingressCount: count });
      }
    }
    return { id: d.id, title: d.title_en, derived: d.derived === true, confidence: d.confidence || null, inCluster };
  });

  // Network (SPEC 5.7): LoadBalancer and NodePort Services selecting a controller's pods
  const services = [];
  for (const s of snapshot.services || []) {
    const m = md(s); const spec = isObj(s.spec) ? s.spec : {};
    if (spec.type !== 'LoadBalancer' && spec.type !== 'NodePort') continue;
    const selector = isObj(spec.selector) ? spec.selector : {};
    const selKeys = Object.keys(selector);
    if (!selKeys.length) continue;
    const ns = String(m.namespace || '');
    const matched = controllers.filter((c) => c.namespace === ns && selKeys.every((k) => c.podLabels[k] === String(selector[k]))).map((c) => c.id);
    if (!matched.length) continue;
    const anns = isObj(m.annotations) ? m.annotations : {};
    const findings = [];
    for (const key of ownKeys(anns)) {
      const entry = idx.ecoService.lookup(key);
      if (entry) findings.push({ key, value: String(anns[key]), ...catalogInfo(entry, matchValueRule(entry.valueRules, anns[key])) });
    }
    for (const entry of idx.serviceFields) {
      const [field, expected] = entry.key.slice('Service.spec.'.length).split('=');
      const actual = spec[field];
      const present = actual !== undefined && actual !== null && actual !== '';
      if (present && (expected === undefined || String(actual) === expected)) findings.push({ key: entry.key, value: String(actual), ...catalogInfo(entry, matchValueRule(entry.valueRules, actual)) });
    }
    const lbIngress = s.status && s.status.loadBalancer && Array.isArray(s.status.loadBalancer.ingress) ? s.status.loadBalancer.ingress : [];
    services.push({
      namespace: ns, name: String(m.name || ''), type: spec.type, controllers: matched,
      addresses: lbIngress.filter(isObj).map((a) => (a.ip ? { ip: String(a.ip) } : a.hostname ? { hostname: String(a.hostname) } : null)).filter(Boolean),
      internal: String(anns[LB_INTERNAL] || '').trim().toLowerCase() === 'true',
      pipName: typeof anns[LB_PIP_NAME] === 'string' ? anns[LB_PIP_NAME] : null,
      ipv4: typeof anns[LB_IPV4] === 'string' ? anns[LB_IPV4] : null,
      loadBalancerIP: typeof spec.loadBalancerIP === 'string' && spec.loadBalancerIP ? spec.loadBalancerIP : null,
      externalTrafficPolicy: typeof spec.externalTrafficPolicy === 'string' ? spec.externalTrafficPolicy : null,
      ports: (Array.isArray(spec.ports) ? spec.ports : []).filter(isObj).map((p) => ({ name: p.name ? String(p.name) : null, port: p.port, protocol: p.protocol || 'TCP', nodePort: p.nodePort || null })),
      findings: findings.sort((a, b) => cmp(a.key, b.key)),
    });
  }
  services.sort(byRef);

  // Gateway API already present (SPEC 5.8)
  const gatewayClasses = (snapshot.gatewayClasses || []).map((o) => {
    const name = String(md(o).name || '');
    const controllerName = o.spec && typeof o.spec.controllerName === 'string' ? o.spec.controllerName : '';
    const hit = (det.gatewayClasses || []).find((x) => (x.name && x.name === name) || (x.controllerName && x.controllerName === controllerName));
    return { name, controllerName, target: hit ? hit.target : null };
  }).sort((a, b) => cmp(a.name, b.name));
  const gatewaysByClass = {};
  for (const gw of snapshot.gateways || []) {
    const cls = gw.spec && typeof gw.spec.gatewayClassName === 'string' ? gw.spec.gatewayClassName : '';
    gatewaysByClass[cls] = (gatewaysByClass[cls] || 0) + 1;
  }
  const gatewayApi = {
    crd: snapshot.gatewayCrd || null,
    gatewayClasses,
    gateways: snapshot.gateways ? snapshot.gateways.length : null,
    gatewaysByClass: Object.fromEntries(Object.keys(gatewaysByClass).sort(cmp).map((k) => [k, gatewaysByClass[k]])),
    httpRoutes: snapshot.httpRoutes ? snapshot.httpRoutes.length : null,
    enabledTargets: uniqSorted(gatewayClasses.map((g) => g.target).filter(Boolean)).sort((a, b) => TARGETS.indexOf(a) - TARGETS.indexOf(b)),
  };

  // AKS application routing add-on
  const appRouting = {
    namespace: (det.appRouting && det.appRouting.namespace) || null,
    controllers: controllers.filter((c) => c.appRouting).map((c) => c.id),
    nics: snapshot.nics ? snapshot.nics.map((o) => {
      const spec = isObj(o.spec) ? o.spec : {};
      const lb = isObj(spec.loadBalancerAnnotations) ? spec.loadBalancerAnnotations : {};
      return { name: String(md(o).name || ''), ingressClassName: typeof spec.ingressClassName === 'string' ? spec.ingressClassName : null, loadBalancerAnnotations: ownKeys(lb).map((k) => ({ key: k, value: String(lb[k]) })) };
    }).sort((a, b) => cmp(a.name, b.name)) : null,
  };

  // Next steps: one ingress2gateway run per class name the served Ingresses use
  const classNames = uniqSorted(servedIngs.map((i) => (i.className !== null ? i.className : i.classAnnotation)).filter((x) => x !== null && x !== ''));
  const i2g = meta.ingress2gateway || {};
  const nextSteps = {
    version: i2g.version || null, source: i2g.source || null, classlessServed: classless,
    commands: (classNames.length ? classNames : uniqSorted(controllers.flatMap((c) => c.ownedClasses))).map((cls) => ({ className: cls, command: ingress2gatewayCommand(i2g.command, cls) })),
  };

  // Output model (identifiers stay in known fields so that anonymize() can replace them)
  const version = isObj(snapshot.version) && isObj(snapshot.version.serverVersion) ? snapshot.version.serverVersion : null;
  return {
    schemaVersion: SCHEMA_VERSION,
    tool: { name: TOOL_NAME, version: VERSION },
    catalog: { date: meta.catalogDate || null, versions: meta.versions || {} },
    generatedAt: nowIso(now),
    mode: snapshot.mode,
    anonymized,
    context: snapshot.context || 'unknown-context',
    cluster: { serverVersion: version && typeof version.gitVersion === 'string' ? version.gitVersion : null },
    collection: {
      warnings: snapshot.warnings.map((w) => ({ code: w.code, params: { ...w.params } })),
      notes: snapshot.notes.map((n) => ({ code: n.code, params: { ...n.params } })),
      deploymentsRead: snapshot.deployments !== null || snapshot.daemonsets !== null,
      ingressClassesRead: snapshot.ingressClasses !== null,
    },
    controllers: controllers.map((c) => ({
      id: c.id, kind: c.kind, namespace: c.namespace, name: c.name, container: c.container, replicas: c.replicas,
      image: c.image, repository: c.repository, tag: c.tag, digest: c.digest, imageFamily: c.imageFamily, version: c.version,
      appRouting: !!c.appRouting, flags: c.flags, flagsSet: c.flagsSet, podLabels: c.podLabels, ownedClasses: c.ownedClasses,
      servedIngresses: c.served.length, verdict: c.verdict,
    })),
    ingressClasses: classes.map((cl) => ({
      name: cl.name, controller: cl.controller, isDefault: cl.isDefault,
      owners: controllers.filter((c) => c.owned.has(cl.name)).map((c) => c.id),
      family: cl.label ? cl.label.family : null, label: cl.label ? cl.label.label : null, source: cl.label ? cl.label.source : null,
    })),
    ingresses: ings.map((ing) => {
      const buckets = bucketsByIngress.get(ing) || {};
      return {
        namespace: ing.namespace, name: ing.name, className: ing.className, classAnnotation: ing.classAnnotation,
        servedBy: ing.servedBy, via: ing.via, selectorNotEvaluated: ing.selectorNotEvaluated, placement: ing.placement,
        hosts: ing.hosts, tlsHosts: ing.tlsHosts, tlsSecrets: ing.tlsSecrets, defaultBackend: ing.defaultBackend,
        routes: ing.routes.map((r) => ({ host: r.host, path: r.path, pathType: r.pathType })), routeCount: ing.routeCount,
        implementationSpecificPaths: ing.implementationSpecific, backendServices: ing.backends,
        keysByBucket: Object.fromEntries(BUCKET_ORDER.filter((b) => buckets[b]).map((b) => [b, buckets[b].size])),
      };
    }),
    scope,
    profile: profileOf(annotations, servedIngs.length),
    annotations,
    otherAnnotationKeys: otherKeys.size,
    ingressClassAnnotations: classRows,
    regexHosts,
    ambiguities,
    configMaps,
    tcpUdp,
    security,
    defaults,
    network: { services },
    gatewayApi,
    appRouting,
    nextSteps,
  };
}

// Translation profile: distinct keys and Ingresses per bucket.
function profileOf(rows) {
  const out = {};
  for (const b of BUCKET_ORDER) {
    const inBucket = rows.filter((r) => r.bucket === b);
    const refs = new Set();
    for (const r of inBucket) for (const ref of r.ingresses) refs.add(refKey(ref));
    out[b] = { keys: new Set(inBucket.map((r) => displayKey(r))).size, ingresses: refs.size };
  }
  return out;
}

// The catalog's ingress2gateway command with the class flag set to one class name.
export function ingress2gatewayCommand(template, className) {
  const cmd = String(template || '');
  const re = /(--ingress-nginx-ingress-class(?:=|\s+))(\S+)/;
  if (re.test(cmd)) return cmd.replace(re, (m, flag) => `${flag}${className}`);
  return cmd.replace(/\bprint\b/, `print --ingress-nginx-ingress-class=${className}`);
}

// ---------------------------------------------------------------------------------------------
// Strings and French typography
// ---------------------------------------------------------------------------------------------

const fill = (s, params = {}) => String(s).replace(/\{(\w+)\}/g, (m, k) => (params[k] === undefined || params[k] === null ? m : String(params[k])));
export function t(lang, key, params) {
  const s = (I18N[lang] && I18N[lang][key] !== undefined) ? I18N[lang][key] : I18N.en[key];
  return s === undefined ? key : fill(s, params);
}

// Non-breaking spaces before : ; ! ? and inside « », outside code, URLs and table separator lines.
function typoLine(line) {
  if (/^\s*\|?\s*:?-{3,}/.test(line)) return line;
  return line.split(/(`[^`]*`|\]\([^)]*\)|https?:\/\/\S+)/).map((seg, i) => (i % 2 ? seg : seg
    .replace(/(?<=[^\s|]) ([;!?])(?=\s|$)/g, ' $1')
    .replace(/(?<=[^\s|]) :(?=\s|$)/g, ' :')
    .replace(/(?<=[A-Za-zÀ-ÿ0-9)\]'"»])(?<!&[a-z]{2,8}):(?=\s)/g, ' :')
    .replace(/(?<=[A-Za-zÀ-ÿ0-9)\]'"»])(?<!&[a-z]{2,8});(?=\s)/g, ' ;')
    .replace(/« /g, '« ')
    .replace(/ »/g, ' »'))).join('').replace(/`([:;])(?= )/g, (m, c) => `\`${c === ':' ? ' ' : ' '}${c}`);
}
export function frTypo(text) {
  return String(text).split(/(```[\s\S]*?```)/).map((block, i) => (i % 2 ? block : block.split('\n').map(typoLine).join('\n'))).join('');
}

// ---------------------------------------------------------------------------------------------
// Anonymization: stable pseudonyms (HMAC-SHA256 with a random salt per run), structure kept
// ---------------------------------------------------------------------------------------------

const PSEUDO = {
  cluster: (h) => `cluster-${h}`, ns: (h) => `ns-${h}`, ing: (h) => `ing-${h}`, svc: (h) => `svc-${h}`, wl: (h) => `wl-${h}`,
  host: (h) => `h-${h}.example`, sec: (h) => `sec-${h}`, ip: (h) => `ip-${h}`, cidr: (h) => `cidr-${h}`, path: (h) => `p-${h}`,
  pip: (h) => `pip-${h}`, reg: (h) => `registry-${h}.example`, val: (h) => `v-${h}`, mail: (h) => `user-${h}@example.com`,
};
// Names that identify no one and keep the report readable.
const KEEP_NAMESPACES = new Set(['default', 'kube-system', 'kube-public', 'kube-node-lease', 'ingress-nginx', 'app-routing-system', 'aks-istio-system', 'aks-istio-ingress', 'azure-alb-system', 'cert-manager']);
const KEEP_NAMES = new Set(['ingress-nginx-controller', 'ingress-nginx-controller-admission', 'nginx', 'controller', 'default', 'ingress-nginx', 'nginx-ingress-controller']);
const KEEP_LABEL_VALUES = new Set(['controller', 'ingress-nginx', 'Helm', 'aks-app-routing-operator', 'aks', 'nginx', 'true', 'false']);
const PUBLIC_REGISTRIES = new Set(['registry.k8s.io', 'k8s.gcr.io', 'gcr.io', 'us.gcr.io', 'eu.gcr.io', 'asia.gcr.io', 'quay.io', 'mcr.microsoft.com', 'docker.io', 'ghcr.io', 'public.ecr.aws', 'cgr.dev']);

export function anonymize(model, { salt = crypto.randomBytes(16) } = {}) {
  const out = JSON.parse(JSON.stringify(model));
  const entries = {};
  const memo = new Map();
  const pseudo = (cat, value) => {
    const v = String(value);
    if (v === '') return v;
    const k = `${cat}\u0000${v}`;
    if (memo.has(k)) return memo.get(k);
    const h = crypto.createHmac('sha256', salt).update(k).digest('hex');
    let len = 6; let p = PSEUDO[cat](h.slice(0, len));
    while (entries[p] && entries[p].value !== v) p = PSEUDO[cat](h.slice(0, ++len));
    memo.set(k, p); entries[p] = { category: cat, value: v };
    return p;
  };
  const ns = (v) => (v === null || v === undefined || KEEP_NAMESPACES.has(v) ? v : pseudo('ns', v));
  const name = (cat, v) => (v === null || v === undefined || KEEP_NAMES.has(v) ? v : pseudo(cat, v));
  const host = (v) => {
    if (v === null || v === undefined || v === '*') return v;
    return v.startsWith('*.') ? `*.${pseudo('host', v.slice(2))}` : pseudo('host', v);
  };
  const urlPath = (p) => String(p).split('/').map((seg) => (seg === '' ? seg : pseudo('path', seg))).join('/');
  const ref = (r) => (r ? Object.assign(r, { namespace: ns(r.namespace), name: name('ing', r.name) }) : r);
  const nsName = (v, cat) => {
    const m = String(v).match(/^([^/\s]+)\/([^/\s]+)$/);
    return m ? `${ns(m[1])}/${name(cat, m[2])}` : scrub(v);
  };

  // Free text: URLs, e-mails, CIDRs, IPs, host names, then every known identifier as a whole token.
  const known = new Map();
  const remember = (orig, p) => { if (orig && p && orig !== p && orig.length >= 3) known.set(orig, p); };
  function scrub(text) {
    if (text === null || text === undefined) return text;
    let s = String(text)
      .replace(/\b([a-z][a-z0-9+.-]*):\/\/([^\s/"'<>?#]+)([^\s"'<>]*)/gi, (m, scheme, h, rest) => `${scheme}://${host(h.replace(/:\d+$/, ''))}${/:\d+$/.test(h) ? h.match(/:\d+$/)[0] : ''}${rest ? urlPath(rest) : ''}`)
      .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, (m) => pseudo('mail', m))
      .replace(/\b\d{1,3}(?:\.\d{1,3}){3}\/\d{1,2}\b/g, (m) => pseudo('cidr', m))
      .replace(/\b\d{1,3}(?:\.\d{1,3}){3}\b/g, (m) => pseudo('ip', m))
      .replace(/\b(?:[0-9a-f]{1,4}:){2,7}[0-9a-f]{0,4}(?:\/\d{1,3})?/gi, (m) => pseudo(m.includes('/') ? 'cidr' : 'ip', m))
      .replace(/(?<![\w.-])(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z][a-z0-9-]{1,62}(?![\w-])(?!\.\w)/gi, (m) => (/\.example$/.test(m) ? m : host(m)));
    const tokens = [...known.keys()].sort((a, b) => b.length - a.length);
    for (const tok of tokens) {
      const re = new RegExp(`(^|[^A-Za-z0-9_.-])${tok.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?=$|[^A-Za-z0-9_.-])`, 'g');
      s = s.replace(re, (m, pre) => `${pre}${known.get(tok)}`);
    }
    return s;
  }
  // Free-form values that name Azure resources or third-party objects: pseudonymised unless boolean or numeric.
  const opaque = (v) => {
    if (v === null || v === undefined || /^(true|false|d+(.d+)?[a-z]*)$/i.test(String(v).trim())) return v;
    const sv = scrub(v);
    return sv !== String(v) ? sv : pseudo('val', v);
  };
  const image = (img) => {
    const s = String(img || '');
    const first = s.split('/')[0];
    return s.includes('/') && first.includes('.') && !PUBLIC_REGISTRIES.has(first) ? `${pseudo('reg', first)}${s.slice(first.length)}` : s;
  };

  // Register identifiers first so free text can be scrubbed consistently.
  for (const i of out.ingresses) {
    remember(i.namespace, ns(i.namespace)); remember(i.name, name('ing', i.name));
    i.backendServices.forEach((s) => remember(s, name('svc', s)));
    i.tlsSecrets.forEach((s) => remember(s, name('sec', s)));
  }
  for (const c of out.controllers) { remember(c.namespace, ns(c.namespace)); remember(c.name, name('wl', c.name)); }
  for (const s of out.network.services) { remember(s.namespace, ns(s.namespace)); remember(s.name, name('svc', s.name)); }

  out.anonymized = true;
  out.context = pseudo('cluster', out.context);
  for (const w of [...out.collection.warnings, ...out.collection.notes]) {
    const p = w.params || {};
    if (p.ref) p.ref = { namespace: ns(p.ref.namespace), name: name('svc', p.ref.name) };
    if (p.value !== undefined) p.value = scrub(p.value);
    if (p.dir !== undefined) p.dir = scrub(p.dir);
  }
  for (const c of out.controllers) {
    c.namespace = ns(c.namespace); c.name = name('wl', c.name); c.container = name('wl', c.container);
    c.image = image(c.image); c.repository = image(c.repository);
    for (const f of ['--configmap', '--tcp-services-configmap', '--udp-services-configmap', '--publish-service', '--default-ssl-certificate', '--default-backend-service']) {
      if (c.flags[f]) c.flags[f] = nsName(c.flags[f], f === '--default-ssl-certificate' ? 'sec' : 'svc');
    }
    if (c.flags['--watch-namespace']) c.flags['--watch-namespace'] = ns(c.flags['--watch-namespace']);
    for (const f of ['--publish-status-address', '--watch-namespace-selector']) if (c.flags[f]) c.flags[f] = scrub(c.flags[f]);
    for (const k of Object.keys(c.podLabels)) {
      const v = c.podLabels[k];
      if (!KEEP_LABEL_VALUES.has(v) && !/^v?\d[\w.+-]*$/.test(v) && !/^ingress-nginx-\d/.test(v)) c.podLabels[k] = pseudo('val', v);
    }
  }
  for (const i of out.ingresses) {
    i.namespace = ns(i.namespace); i.name = name('ing', i.name);
    i.hosts = i.hosts.map(host); i.tlsHosts = i.tlsHosts.map(host);
    i.tlsSecrets = i.tlsSecrets.map((s) => name('sec', s));
    i.backendServices = i.backendServices.map((s) => name('svc', s));
    i.routes = i.routes.map((r) => ({ host: host(r.host), path: urlPath(r.path), pathType: r.pathType }));
  }
  for (const row of out.annotations) {
    row.ingresses.forEach(ref);
    row.values = row.values.map((v) => (v.value !== undefined ? { value: row.kind === 'ecosystem' ? opaque(v.value) : scrub(v.value) } : v));
  }
  for (const row of out.ingressClassAnnotations) row.value = scrub(row.value);
  for (const r of out.regexHosts) { r.host = host(r.host); r.ingresses.forEach(ref); r.triggers.forEach(ref); }
  for (const a of out.ambiguities) ref(a.ingress);
  for (const cm of out.configMaps) {
    cm.namespace = ns(cm.namespace); cm.name = name('svc', cm.name); cm.unresolved = scrub(cm.unresolved);
    for (const k of cm.keys) if (k.value !== undefined) k.value = scrub(k.value);
  }
  for (const g of out.tcpUdp) {
    g.namespace = ns(g.namespace); g.name = name('svc', g.name); g.unresolved = scrub(g.unresolved);
    for (const e of g.entries) { e.namespace = ns(e.namespace); e.service = name('svc', e.service); e.raw = scrub(e.raw); }
  }
  for (const s of out.security) if (s.configMap) s.configMap = { namespace: ns(s.configMap.namespace), name: name('svc', s.configMap.name) };
  for (const d of out.defaults) {
    for (const x of d.inCluster) {
      if (x.configMap) x.configMap = { namespace: ns(x.configMap.namespace), name: name('svc', x.configMap.name) };
      if (x.value !== undefined) x.value = scrub(x.value);
    }
  }
  for (const s of out.network.services) {
    s.namespace = ns(s.namespace); s.name = name('svc', s.name);
    s.addresses = s.addresses.map((a) => (a.ip ? { ip: pseudo('ip', a.ip) } : { hostname: host(a.hostname) }));
    s.pipName = s.pipName === null ? null : pseudo('pip', s.pipName);
    s.ipv4 = s.ipv4 === null ? null : pseudo('ip', s.ipv4);
    s.loadBalancerIP = s.loadBalancerIP === null ? null : pseudo('ip', s.loadBalancerIP);
    for (const f of s.findings) f.value = opaque(f.value);
  }
  if (out.appRouting.nics) {
    for (const n of out.appRouting.nics) {
      n.name = name('wl', n.name);
      for (const a of n.loadBalancerAnnotations) a.value = opaque(a.value);
    }
  }
  const map = { DO_NOT_SHARE: 'This file maps the pseudonyms of the anonymized report back to real names. Keep it on this machine; never send it.', generatedAt: out.generatedAt, entries: {} };
  for (const p of Object.keys(entries).sort(cmp)) map.entries[p] = entries[p];
  return { model: out, map };
}

// ---------------------------------------------------------------------------------------------
// Rendering: report.md, console summary
// ---------------------------------------------------------------------------------------------

const SUPPORT_MARK = { yes: '✓', partial: '~', no: '✗', unknown: '?', 'n/a': '–' };
const mark = (s) => SUPPORT_MARK[s] || '?';
const code = (v) => { const s = String(v); return s.includes('`') ? `\`\` ${s} \`\`` : `\`${s}\``; };
const cell = (v) => String(v === null || v === undefined ? '' : v).replace(/\\/g, '\\\\').replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
const trunc = (v, n = VALUE_MAX) => { const s = String(v); return s.length > n ? `${s.slice(0, n - 1)}…` : s; };
const refText = (r) => `${r.namespace}/${r.name}`;
// Catalog prose in Markdown: escape what GitHub would read as HTML, emphasis or code.
const prose = (v) => String(v === null || v === undefined ? '' : v).replace(/\\/g, '\\\\').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\*/g, '\\*').replace(/`/g, '\\`');

function controllerName(model, id) {
  const c = model.controllers.find((x) => x.id === id);
  return c ? `${c.namespace}/${c.name}` : id;
}
function verdictText(lang, v) {
  if (v.status === 'vulnerable') return t(lang, 'verdict.vulnerable', { count: v.unfixed.length });
  if (v.status === 'vendor') return t(lang, `verdict.vendor.${v.reason}`);
  return t(lang, `verdict.${v.status}`);
}
function noteOf(lang, row) {
  if (row.note) return prose(row.note[lang] || row.note.en || '');
  return row.noteCode ? t(lang, `note.${row.noteCode}`) : '';
}
function messageOf(lang, m) {
  const p = { ...m.params };
  if (p.ref && typeof p.ref === 'object') p.ref = refText(p.ref);
  const text = t(lang, m.code, p);
  return m.detail ? `${text} (${m.detail})` : text;
}

export function renderMarkdown(model, { lang = 'en', catalog = CATALOG } = {}) {
  const L = (key, params) => t(lang, key, params);
  const meta = catalog.meta || {};
  const targetsMeta = meta.targets || {};
  const short = (id) => (targetsMeta[id] && targetsMeta[id].short) || id;
  const tName = (id) => (targetsMeta[id] && targetsMeta[id][`name_${lang}`]) || id;
  const th = { t1: short('appRoutingGateway'), t2: short('agc'), t3: short('agcIngress'), t4: short('istio') };
  const supportCells = (targets) => TARGETS.map((x) => mark(targets && targets[x])).join(' | ');
  const out = [];
  const p = (...lines) => out.push(...lines);
  const cname = (id) => controllerName(model, id);

  // 0. Title and metadata
  p(`# ${L('r.title', { context: model.context })}`, '');
  p(`- ${L('r.meta.context')}: ${code(model.context)}`);
  p(`- ${L('r.meta.generated')}: ${model.generatedAt}`);
  p(`- ${L('r.meta.tool')}: ${model.tool.name} ${model.tool.version}; ${L('r.meta.catalog')}: ${model.catalog.date || '?'}`);
  p(`- ${L('r.meta.mode')}: ${L(model.mode === 'offline' ? 'r.meta.offline' : 'r.meta.live')}; ${L('r.meta.anonymized')}: ${L(model.anonymized ? 'r.yes' : 'r.no')}`);
  if (model.cluster.serverVersion) p(`- ${L('r.meta.server')}: ${model.cluster.serverVersion}`);
  p('', `> ${L(model.mode === 'offline' ? 'r.readOnlyOffline' : 'r.readOnly')}`, '');

  // 1. Summary
  p(`## ${L('r.s1')}`, '', `### ${L('r.s1.controllers')}`, '');
  if (!model.controllers.length) p(L('r.s1.noController'));
  for (const c of model.controllers) {
    const family = c.imageFamily ? c.imageFamily.label : c.repository;
    const reps = c.replicas === null ? '' : `, ${c.replicas}×`;
    p(`- ${code(`${c.namespace}/${c.name}`)} (${c.kind}${reps}): ${family}${c.version ? ` ${code(c.version)}` : ''}: ${verdictText(lang, c.verdict)}; ${c.servedIngresses} Ingress; IngressClass: ${c.ownedClasses.length ? c.ownedClasses.map(code).join(', ') : L('r.none')}`);
  }
  p('', `### ${L('r.s1.status')}`, '');
  for (const s of meta.status || []) p(`- ${s.date}: ${prose(s[`text_${lang}`] || s.text_en)} [source](${s.source})`);
  p('', `### ${L('r.s1.security')}`, '');
  if (!model.security.length) p(L('r.s1.noSecurity'));
  for (const s of model.security) {
    const cm = s.configMap ? code(refText(s.configMap)) : '';
    const cves = s.cves ? s.cves.join(', ') : '';
    p(`- ${L(`sec.${s.code}`, { controller: s.controller ? code(cname(s.controller)) : '', count: s.cves ? s.cves.length : s.ingressCount, cves, cm, keys: (s.keys || []).join(', ') })}`);
  }
  const sc = model.scope;
  p('', `### ${L('r.s1.scope')}`, '');
  p(L('r.s1.scopeLine', { ingresses: sc.ingresses, total: sc.ingressesTotal, namespaces: sc.namespaces, routes: sc.routes, defaultBackends: sc.defaultBackends, hosts: sc.hosts, tlsHosts: sc.tlsHosts, tlsSecrets: sc.tlsSecrets, backends: sc.backendServices }));
  p('', L('r.s1.matching', { regex: sc.regexPaths, implSpecific: sc.implementationSpecificPaths, classless: sc.classless }));
  p('', `### ${L('r.s1.profile')}`, '', L('r.s1.profileHead'), '|---|---:|---:|---|');
  for (const b of BUCKET_ORDER) p(`| ${b} | ${model.profile[b].keys} | ${model.profile[b].ingresses} | ${cell(L(`r.bucket.${b}`))} |`);
  p('', `### ${L('r.s1.addresses')}`, '');
  const lbs = model.network.services.filter((s) => s.addresses.length);
  if (!lbs.length) p(L('r.s1.noAddresses'));
  for (const s of lbs) p(`- ${code(`${s.namespace}/${s.name}`)}: ${s.addresses.map((a) => code(a.ip || a.hostname)).join(', ')}`);
  p('', `### ${L('r.s1.targets')}`, '');
  const ga = model.gatewayApi;
  if (!ga.gatewayClasses.length) p(L('r.s1.noGatewayApi'));
  else for (const g of ga.gatewayClasses) p(`- ${code(g.name)} (${code(g.controllerName || '?')})${g.target ? `: ${tName(g.target)}` : ''}`);
  if (ga.crd) p('', L('r.s1.crd', { version: ga.crd.bundleVersion || '?', channel: ga.crd.channel || '?' }));
  if (ga.enabledTargets.length) p('', L('r.s1.enabled', { targets: ga.enabledTargets.map(tName).join(', ') }));
  p('', L('r.s1.next'), '');

  // 2. Annotations
  p(`## ${L('r.s2')}`, '');
  if (!model.annotations.length) p(L('r.s2.none'));
  else {
    p(L('r.s2.intro'), '', L('r.s2.head', th), '|---|---:|---|---|---|---|---|---|---|---|');
    for (const r of model.annotations) {
      const values = r.values.map((v) => (v.lines !== undefined ? L('r.s2.lines', { n: v.lines }) : code(trunc(v.value)))).join(', ') + (r.moreValues ? ` ${L('r.s2.more', { n: r.moreValues })}` : '');
      const key = r.rule ? `${code(displayKey(r))} (${prose(r.rule.when)})` : code(displayKey(r));
      const gw = r.gatewayApi && r.gatewayApi.construct !== 'none' ? `${prose(r.gatewayApi.construct)} (${r.gatewayApi.channel}, ${r.gatewayApi.support})` : '–';
      p(`| ${cell(key)} | ${r.ingressCount} | ${cell(values)} | ${r.bucket} | ${cell(gw)} | ${supportCells(r.targets)} | ${cell(noteOf(lang, r))} |`);
    }
    p('', L('r.s2.legend'));
  }
  if (model.otherAnnotationKeys) p('', L('r.s2.other', { n: model.otherAnnotationKeys }));
  if (model.regexHosts.length) {
    p('', `### ${L('r.s2.regex')}`, '', L('r.s2.regexIntro'), '');
    for (const h of model.regexHosts) p(`- ${L('r.s2.regexLine', { host: code(h.host), ingresses: h.ingresses.length, triggers: h.triggers.map((x) => `${code(x.key)} (${refText(x)})`).join(', ') })}`);
  }
  if (model.ingressClassAnnotations.length) {
    p('', `### ${L('r.s2.classAnn')}`, '');
    for (const r of model.ingressClassAnnotations) p(`- ${code(r.className)}: ${code(`${r.key}=${r.value}`)}: ${noteOf(lang, r)}`);
  }
  p('');

  // 3. Controller settings
  p(`## ${L('r.s3')}`, '');
  if (!model.configMaps.length) p(L('r.s3.none'), '');
  for (const cm of model.configMaps) {
    const name = cm.namespace ? `${cm.namespace}/${cm.name}` : cm.unresolved;
    if (!cm.found) { p(L('r.s3.notFound', { cm: code(name) }), ''); continue; }
    p(`### ${L('r.s3.cm', { cm: name, controllers: cm.controllers.map(cname).join(', ') })}`, '');
    const changed = cm.keys.filter((k) => !k.sameAsDefault);
    const same = cm.keys.filter((k) => k.sameAsDefault);
    if (!cm.keys.length) p(L('r.s3.empty'));
    if (changed.length) {
      p(L('r.s3.head', th), '|---|---|---|---|---|---|---|---|');
      for (const k of changed) {
        const value = k.snippet ? L('r.s2.lines', { n: k.lines }) : code(trunc(k.value));
        p(`| ${cell(code(k.key))} | ${cell(value)} | ${k.bucket} | ${supportCells(k.targets)} | ${cell(noteOf(lang, k))} |`);
      }
    }
    if (same.length) p('', L('r.s3.defaults', { keys: same.map((k) => code(k.key)).join(', ') }));
    p('');
  }

  // 4. Defaults that change
  p(`## ${L('r.s4')}`, '', L('r.s4.intro'), '');
  const defById = new Map((catalog.defaults || []).map((d) => [d.id, d]));
  for (const d of model.defaults) {
    const c = defById.get(d.id);
    if (!c) continue;
    const loc = (o, f) => o[`${f}_${lang}`] || o[`${f}_en`];
    const flags = [d.inCluster.length ? L('r.s4.overridden') : null, d.derived ? L('r.s4.derived') : null].filter(Boolean);
    p('<details>', `<summary>${d.id}. ${prose(loc(c, 'title'))}${flags.length ? ` (${flags.join('; ')})` : ''}</summary>`, '');
    p(`- ${L('r.s4.nginx')}: ${prose(loc(c, 'nginx'))}`);
    const inCluster = d.inCluster.map((x) => {
      if (x.kind === 'configmap') return L('r.s4.cmValue', { cm: code(refText(x.configMap)), key: code(x.key), value: x.lines !== undefined ? L('r.s2.lines', { n: x.lines }) : code(trunc(x.value)) });
      if (x.kind === 'flag') return L('r.s4.flagValue', { controller: code(cname(x.controller)), key: x.key, value: x.value });
      if (x.kind === 'annotation') return L('r.s4.annCount', { key: code(x.key), n: x.ingressCount });
      return code(x.key);
    });
    p(`- ${L('r.s4.inCluster')}: ${inCluster.length ? inCluster.join('; ') : L('r.s4.notChanged')}`);
    for (const x of TARGETS) p(`- ${tName(x)}: ${prose((c.targets[x] && (c.targets[x][lang] || c.targets[x].en)) || '?')}`);
    p(`- ${L('r.s4.impact')}: ${prose(loc(c, 'impact'))}`, `- ${L('r.s4.test')}: ${prose(loc(c, 'test'))}`, '', '</details>', '');
  }

  // 5. TCP/UDP, passthrough, default certificate, default backend
  p(`## ${L('r.s5')}`, '');
  if (!model.tcpUdp.length) p(`- ${L('r.s5.noTcpUdp')}`);
  for (const g of model.tcpUdp) {
    const name = g.namespace ? `${g.namespace}/${g.name}` : g.unresolved;
    p(`- ${L('r.s5.tcpudp', { protocol: g.protocol, cm: code(name), n: g.entries.length })}: ${g.entries.map((e) => code(`${e.port} → ${e.namespace ? `${e.namespace}/${e.service}:${e.servicePort}` : e.raw}`)).join(', ')}. ${noteOf(lang, g)} (${TARGETS.map((x) => `${short(x)} ${mark(g.targets[x])}`).join(', ')})`);
  }
  const pass = model.controllers.filter((c) => flagTrue(c.flags['--enable-ssl-passthrough']));
  const passRows = model.annotations.filter((r) => r.kind === 'annotation' && r.name === 'ssl-passthrough');
  const passCount = passRows.reduce((n, r) => n + r.ingressCount, 0);
  p(`- ${L('r.s5.passthrough', { value: pass.length ? L('r.s5.passthroughOn', { controllers: pass.map((c) => code(`${c.namespace}/${c.name}`)).join(', '), n: passCount }) : L('r.no') })}`);
  for (const c of model.controllers) {
    const cert = c.flags['--default-ssl-certificate'];
    const be = c.flags['--default-backend-service'];
    p(`- ${code(`${c.namespace}/${c.name}`)}: ${L('r.s5.defaultCert', { value: cert ? code(cert) : L('r.s5.noDefaultCert') })}; ${L('r.s5.defaultBackend', { value: be ? code(be) : L('r.s5.noDefaultBackend'), n: c.servedIngresses ? model.scope.defaultBackends : 0 })}`);
  }
  p('');

  // 6. Network
  p(`## ${L('r.s6')}`, '');
  const svcs = model.network.services;
  if (!svcs.length) p(L('r.s6.none'));
  else {
    p(L('r.s6.head'), '|---|---|---|---|---|---|---|');
    for (const s of svcs) {
      const pinned = [s.pipName ? `azure-pip-name ${code(s.pipName)}` : null, s.ipv4 ? `ipv4 ${code(s.ipv4)}` : null, s.loadBalancerIP ? `loadBalancerIP ${code(s.loadBalancerIP)}` : null].filter(Boolean).join(', ') || '–';
      const ports = s.ports.map((x) => `${x.port}/${x.protocol}${x.nodePort ? `:${x.nodePort}` : ''}`).join(', ');
      p(`| ${cell(code(`${s.namespace}/${s.name}`))} | ${s.type} | ${cell(s.addresses.map((a) => a.ip || a.hostname).join(', ') || '–')} | ${L(s.internal ? 'r.yes' : 'r.no')} | ${cell(pinned)} | ${s.externalTrafficPolicy || 'Cluster'} | ${cell(ports)} |`);
    }
    const findings = svcs.flatMap((s) => s.findings.map((f) => ({ s, f })));
    if (findings.length) {
      p('', `### ${L('r.s6.findings')}`, '');
      for (const { s, f } of findings) p(`- ${code(`${s.namespace}/${s.name}`)}: ${code(`${f.key}=${trunc(f.value)}`)} (${f.bucket}): ${noteOf(lang, f)}`);
    }
  }
  p('', `> ${L('r.s6.reminder')}`, '');

  // 7. Inventory per namespace
  p(`## ${L('r.s7')}`, '');
  const served = model.ingresses.filter((i) => i.servedBy.length);
  if (!served.length) p(L('r.s7.none'), '');
  const byNs = new Map();
  for (const i of served) { if (!byNs.has(i.namespace)) byNs.set(i.namespace, []); byNs.get(i.namespace).push(i); }
  for (const nsName of [...byNs.keys()].sort(cmp)) {
    const list = byNs.get(nsName);
    p('<details>', `<summary>${L('r.s7.summary', { ns: nsName, n: list.length, routes: list.reduce((n, i) => n + i.routeCount, 0) })}</summary>`, '', L('r.s7.head'), '|---|---|---|---:|---|---|');
    for (const i of list) {
      const cls = i.className !== null ? i.className : i.classAnnotation !== null ? `${i.classAnnotation} (annotation)` : '–';
      const hosts = i.hosts.slice(0, 3).join(', ') + (i.hosts.length > 3 ? ` +${i.hosts.length - 3}` : '');
      const keys = BUCKET_ORDER.filter((b) => i.keysByBucket[b]).map((b) => `${b} ${i.keysByBucket[b]}`).join(', ') || '–';
      p(`| ${cell(code(i.name))} | ${cell(cls)} | ${cell(hosts || '*')} | ${i.routeCount} | ${L(i.tlsHosts.length || i.tlsSecrets.length ? 'r.yes' : 'r.no')} | ${cell(keys)} |`);
    }
    p('', '</details>', '');
  }

  // 8. Other controllers, unassigned, ambiguities
  p(`## ${L('r.s8')}`, '', `### ${L('r.s8.other')}`, '');
  const others = model.ingresses.filter((i) => i.placement && i.placement.status === 'other');
  if (!others.length) p(L('r.s8.none'));
  const byLabel = new Map();
  for (const i of others) { const k = i.placement.label; if (!byLabel.has(k)) byLabel.set(k, []); byLabel.get(k).push(i); }
  for (const label of [...byLabel.keys()].sort(cmp)) p(`- ${label}: ${byLabel.get(label).map((i) => code(refText(i))).join(', ')}`);
  p('', `### ${L('r.s8.unassigned')}`, '');
  const unassigned = model.ingresses.filter((i) => i.placement && i.placement.status === 'unassigned');
  if (!unassigned.length) p(L('r.s8.none'));
  for (const i of unassigned) {
    const pl = i.placement;
    p(`- ${code(refText(i))}: ${L(`reason.${pl.reason}`, { class: pl.className ? code(pl.className) : '', controller: pl.controllerString ? code(pl.controllerString) : '' })}${pl.controller ? ` (${code(cname(pl.controller))})` : ''}`);
  }
  p('', `### ${L('r.s8.ambiguities')}`, '');
  if (!model.ambiguities.length) p(L('r.s8.none'));
  for (const a of model.ambiguities) {
    p(`- ${L(`amb.${a.type}`, { ingress: code(refText(a.ingress)), controllers: (a.controllers || []).map((id) => code(cname(id))).join(', '), class: a.className ? code(a.className) : '', annotation: a.annotation !== undefined ? code(a.annotation) : '' })}`);
  }
  p('');

  // 9. Next steps
  const ns9 = model.nextSteps;
  p(`## ${L('r.s9')}`, '');
  p(`1. ${L('r.s9.target', { enabled: ga.enabledTargets.length ? L('r.s9.targetSome', { targets: ga.enabledTargets.map(tName).join(', ') }) : L('r.s9.targetNone') })}`);
  for (const x of TARGETS) p(`   - ${tName(x)}: ${targetsMeta[x] ? targetsMeta[x].docs : ''}`);
  p(`2. ${L('r.s9.i2g', { version: ns9.version || '' })}`, '', '   ```bash');
  for (const c of ns9.commands) p(`   ${c.command}`);
  p('   ```', '', `   ${L('r.s9.i2gNotes', { classless: ns9.classlessServed })}`);
  p(`3. ${L('r.s9.items')}`, `4. ${L('r.s9.network')}`, `5. ${L('r.s9.defaults')}`, `6. ${L('r.s9.cutover')}`, '');
  p(L('r.s9.offer', { url: OFFER_URL[lang] || OFFER_URL.en }), '');

  // 10. About
  const v = meta.versions || {};
  p(`## ${L('r.s10')}`, '');
  p(L('r.s10.catalog', { date: meta.catalogDate || '?', ingressNginx: v.ingressNginx || '?', gatewayApi: v.gatewayApi || '?', i2g: v.ingress2gateway || '?', targets: TARGETS.map((x) => (targetsMeta[x] ? `[${short(x)}](${targetsMeta[x].docs})` : x)).join(', ') }));
  p('', L('r.s10.sources', { repo: REPO_URL }), '', L('r.s10.disclaimer'));
  const caveats = meta[`notes_${lang}`] || meta.notes_en || [];
  if (caveats.length) { p('', `### ${L('r.s10.caveats')}`, ''); for (const c of caveats) p(`- ${prose(c)}`); }
  if (model.collection.warnings.length) { p('', `### ${L('r.s10.warnings')}`, ''); for (const w of model.collection.warnings) p(`- ${messageOf(lang, w)}`); }
  if (model.collection.notes.length) { p('', `### ${L('r.s10.notes')}`, ''); for (const n of model.collection.notes) p(`- ${messageOf(lang, n)}`); }
  p('');

  const text = out.join('\n').replace(/\n{3,}/g, '\n\n');
  return lang === 'fr' ? frTypo(text) : text;
}

export function renderConsole(model, { lang = 'en', files = {} } = {}) {
  const L = (key, params) => t(lang, key, params);
  const pr = model.profile;
  const lines = [
    L('c.title', { tool: model.tool.name, version: model.tool.version }),
    L('c.context', { context: model.context, mode: model.mode }),
    L('c.controllers', { n: model.controllers.length, vulnerable: model.controllers.filter((c) => c.verdict.status === 'vulnerable').length, vendor: model.controllers.filter((c) => c.verdict.status === 'vendor').length }),
    L('c.scope', { ingresses: model.scope.ingresses, total: model.scope.ingressesTotal, namespaces: model.scope.namespaces, routes: model.scope.routes }),
    L('c.profile', { redesign: pr.redesign.keys, unknown: pr.unknown.keys, policy: pr.policy.keys, direct: pr.direct.keys, none: pr.none.keys }),
  ];
  if (model.collection.warnings.length) lines.push(L('c.warnings', { n: model.collection.warnings.length }));
  if (files.report) lines.push(L('c.report', { file: files.report }));
  if (files.json) lines.push(L('c.json', { file: files.json }));
  if (files.map) lines.push(L('c.map', { file: files.map }));
  const text = lines.join('\n');
  return lang === 'fr' ? frTypo(text) : text;
}

// ---------------------------------------------------------------------------------------------
// Output files and main
// ---------------------------------------------------------------------------------------------

export const safeName = (s) => String(s || 'unknown').replace(/[^A-Za-z0-9._-]+/g, '-').replace(/^[-.]+|-+$/g, '').slice(0, 80) || 'unknown';
function stamp(iso) { return String(iso).replace(/[-:]/g, '').replace('T', '-').slice(0, 13); }

// Creates the output directory, or reuses one this tool created (marker file); refuses anything else.
function prepareOutDir(dir) {
  if (fs.existsSync(dir)) {
    const entries = fs.readdirSync(dir);
    if (entries.length && !entries.includes(MARKER_FILE)) throw new UsageError('usage.outNotEmpty', { dir });
  } else fs.mkdirSync(dir, { recursive: true });
}

export function writeOutputs(model, { out, lang, catalog = CATALOG, map = null }) {
  prepareOutDir(out);
  const files = { report: path.join(out, OUTPUT_FILES.report), json: path.join(out, OUTPUT_FILES.json) };
  const write = (file, text) => {
    try { fs.writeFileSync(file, text, 'utf8'); } catch (x) { throw new FatalError('fatal.write', { file, detail: (x && x.code) || String(x) }); }
  };
  write(path.join(out, MARKER_FILE), `${TOOL_NAME} ${VERSION}\n`);
  write(files.report, renderMarkdown(model, { lang, catalog }));
  write(files.json, `${JSON.stringify(model, null, 2)}\n`);
  if (map) { files.map = path.join(out, OUTPUT_FILES.map); write(files.map, `${JSON.stringify(map, null, 2)}\n`); }
  return files;
}

export function main(argv = process.argv.slice(2), env = process.env, io = { out: (s) => process.stdout.write(`${s}\n`), err: (s) => process.stderr.write(`${s}\n`) }) {
  let lang = resolveLang(null, env);
  try {
    const opts = parseArgs(argv);
    lang = resolveLang(opts.lang, env);
    if (opts.help) { io.out(t(lang, 'help', { tool: TOOL_NAME, version: VERSION })); return 0; }
    if (opts.version) { io.out(VERSION); return 0; }
    assertCatalog(CATALOG);
    const now = env.INGRESS_INVENTORY_NOW ? new Date(env.INGRESS_INVENTORY_NOW) : new Date();
    const snapshot = opts.fromDir ? loadFromDir(opts.fromDir, opts) : collectLive(opts);
    let model = analyze(snapshot, { catalog: CATALOG, now });
    let map = null;
    if (opts.anonymize) ({ model, map } = anonymize(model));
    const out = opts.out || path.join('.', `ingress-inventory-${safeName(model.context)}-${stamp(model.generatedAt)}`);
    const files = writeOutputs(model, { out, lang, catalog: CATALOG, map });
    if (opts.quiet) { for (const f of [files.report, files.json, files.map].filter(Boolean)) io.out(f); } else io.out(renderConsole(model, { lang, files }));
    return 0;
  } catch (x) {
    if (x instanceof UsageError) {
      io.err(`${t(lang, 'error.prefix')} ${t(lang, x.key, x.params)}\n${t(lang, 'usage.hint')}`);
      return 2;
    }
    if (x instanceof FatalError) {
      io.err(`${t(lang, 'error.prefix')} ${t(lang, x.key, x.params)}`);
      return 1;
    }
    io.err(`${t(lang, 'error.prefix')} ${x && x.stack ? x.stack : x}`);
    return 1;
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exitCode = main();
